const a=[1,2,3],b=[0,...a,4,...a,5];function sum3(n,i,r){return n+i+r}function variadicSum(...n){return n.reduce(function(n,i){return n+i},0)}print(b.join(",")),print(sum3(...a)),print(variadicSum(...a,...b));const str="abc";print([...str].join("-"));const copy=[...a];copy.push(999),print("original unaffected:",a.join(","),"copy:",copy.join(","));